import{_ as e,o as i,c as r,a2 as t}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Memoria y Familiarity","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/magic/memory-and-familiarity.md","filePath":"es/guide/magic/memory-and-familiarity.md"}'),o={name:"es/guide/magic/memory-and-familiarity.md"};function n(l,a,s,d,c,m){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="memory-familiarity" tabindex="-1">Memoria y Familiarity <a class="header-anchor" href="#memory-familiarity" aria-label="Enlace permanente a &quot;Memoria y Familiarity&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Disponibilidad no confirmada.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Conocer un hechizo permanentemente es distinto de prepararlo en <a href="/Syrolands-Public/es/guide/glossary.html#active-memory">Active Memory</a> (memoria activa).</li><li><a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a> (fluidez práctica) mejora la soltura con un <a href="/Syrolands-Public/es/guide/magic/learning-spells.html">Core Pattern</a> (estructura base del hechizo) sin gastar más límite de <a href="/Syrolands-Public/es/guide/characters/skills.html">habilidades</a>.</li><li>La preparación elimina el tiempo extra de consulta, no los costes o riesgos normales del lanzamiento.</li></ul><p><span id="spell-memory-and-familiarity"></span><span id="at-a-glance"></span><span id="trade-offs"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elemento</th><th>Qué significa para el jugador</th></tr></thead><tbody><tr><td>Conocido</td><td>El patrón se ha aprendido de forma permanente.</td></tr><tr><td>Preparado</td><td>Inicia la secuencia normal de lanzamiento sin una consulta adicional.</td></tr><tr><td>Conocido sin preparar</td><td>Consulta o recuerda el patrón antes del lanzamiento normal; eso genera exposición.</td></tr><tr><td>Learned / Practiced / Mastered</td><td>Grados compartidos de fluidez; sus efectos exactos sobre hechizos y tiempos siguen abiertos.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Orientación de Syrolands</th></tr></thead><tbody><tr><td>Un libro ofrece acceso a sus hechizos, con los requisitos normales de lanzamiento.</td><td>El conocimiento permanente puede superar el conjunto preparado para acceder directamente al lanzamiento normal.</td></tr><tr><td>Magery mide la habilidad general de lanzamiento.</td><td>Familiarity distingue además la práctica con cada patrón.</td></tr></tbody></table><p>Las reglas de UO varían según la época y el shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/magery/" target="_blank" rel="noreferrer">UO oficial: Magery y Meditation</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Mientras te persiguen, puedes conocer Remove Curse pero necesitar consultar el libro porque no estaba preparado. Encontrar el patrón todavía deja pendiente completar el lanzamiento normal.</p><h2 id="progression-trade-offs" tabindex="-1">Progresión y contrapartidas <a class="header-anchor" href="#progression-trade-offs" aria-label="Enlace permanente a &quot;Progresión y contrapartidas&quot;">​</a></h2><p>INT puede apoyar la capacidad y la complejidad; Meditation puede ayudar a reorganizar la preparación. Las variantes pueden necesitar preparación extra. La capacidad, los retrasos, los cambios y los costes siguen abiertos, y los espacios de <a href="/Syrolands-Public/es/guide/combat/special-attacks.html">SAs</a> marciales no definen la memoria mágica. La ausencia de calendario no debería penalizar la fluidez.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity compartida</a> · <a href="/Syrolands-Public/es/guide/magic/spellbooks-scrolls-and-reagents.html">Libros y pergaminos</a> · <a href="/Syrolands-Public/es/guide/magic/meditation-and-concentration.html">Meditation</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p>Consulta la especificación de diseño: <a href="/Syrolands-Public/es/game-design/magic/memory-and-familiarity.html">Memoria y Familiarity</a>.</p><p><span id="shared-practice-states"></span></p>',19)])])}const u=e(o,[["render",n]]);export{h as __pageData,u as default};
